<template><view class="identity-page"><view class="back" @tap="back">‹</view><view class="auth-icon">绿</view><text class="title">选择身份</text><text class="subtitle">请选择要进入的端。</text><view class="roles"><view v-for="role in roles" :key="role.key" :class="['role',selected===role.key?'selected':'']" @tap="selected=role.key"><view class="role-icon">{{role.icon}}</view><view class="role-copy"><text class="role-title">{{role.title}}</text><text class="role-desc">{{role.desc}}</text></view><text v-if="selected===role.key" class="check">✓</text></view></view><view class="primary-btn enter" @tap="enter">进入{{currentRole.title}} →</view></view></template>
<script>import {callCloud,roleHome,saveUserSession} from '../../common/cloud.js';import {toast} from '../../common/mock.js';export default{data(){return{selected:'personal',roles:[{key:'personal',icon:'●',title:'个人端',desc:'低碳生活、积分与活动'},{key:'enterprise',icon:'▣',title:'企业端',desc:'绿色品牌与校园运营'},{key:'campus',icon:'⌂',title:'校园端',desc:'校园碳排与活动管理'}]}},computed:{currentRole(){return this.roles.find(item=>item.key===this.selected)||this.roles[0]}},methods:{back(){uni.navigateBack()},async enter(){const pending=uni.getStorageSync('login_pending');if(!pending)return toast('登录信息已失效');try{const result=await callCloud('user-login',{...pending,role:this.selected});saveUserSession(result.user);uni.removeStorageSync('login_pending');uni.reLaunch({url:roleHome(result.user.role)})}catch(error){toast(error.message||'登录失败')}}}}</script>
<style lang="scss">@import '../../common/portal.scss';.identity-page{min-height:100vh;padding:24rpx 40rpx 60rpx;background:#f7faf9;box-sizing:border-box}.back{width:68rpx;height:68rpx;font-size:58rpx}.auth-icon{display:flex;align-items:center;justify-content:center;width:100rpx;height:100rpx;margin-top:72rpx;border-radius:24rpx;background:#56b36c;color:#00391a;font-size:44rpx}.identity-page .title{display:block;margin-top:36rpx;font-size:54rpx}.identity-page .subtitle{font-size:28rpx}.roles{margin-top:66rpx}.role{display:flex;align-items:center;margin-bottom:18rpx;padding:24rpx;border:2rpx solid #d7dbda;border-radius:24rpx;background:#fff}.role.selected{border-color:#27ae60;background:#d6e6e3}.role-icon{display:flex;align-items:center;justify-content:center;width:72rpx;height:72rpx;margin-right:20rpx;border-radius:20rpx;background:#27ae60;color:#fff;font-size:30rpx}.role-copy{flex:1}.role-title{display:block;font-size:30rpx;font-weight:700}.role-desc{display:block;margin-top:7rpx;color:#6d7a6e;font-size:23rpx}.check{color:#006d37;font-size:36rpx}.enter{height:112rpx;margin-top:76rpx;border-radius:24rpx;font-size:32rpx;font-weight:700}</style>
